mapper.select:
select id, mission_code as missionCode, mission_name as missionName, mission_desc as missionDesc, trigger_event as triggerEvent, exp_reward as expReward, daily_limit as dailyLimit, status, sort_no as sortNo, create_time as createTime, update_time as updateTime from growth_mission
and mission_code like concat('%', #{missionCode}, '%') and mission_name like concat('%', #{missionName}, '%') and trigger_event = #{triggerEvent} and status = #{status}
order by sort_no asc, id desc

mapper.update:
update growth_mission
mission_name = #{missionName}, mission_desc = #{missionDesc}, trigger_event = #{triggerEvent}, exp_reward = #{expReward}, daily_limit = #{dailyLimit}, status = #{status}, sort_no = #{sortNo}, update_time = #{updateTime}
where id = #{id}
